def search(self, word):
    curr_node = self.root
    for char in word:
        if char not in curr_node.children:
            return False
        curr_node = curr_node.children[char]
    return curr_node.is_end_of_word

def login(self, phone_num, password):
    national_id = self.signed_in[password]
    if national_id is not None:
        patient = self.patients[national_id]
        if patient.phone_num == phone_num:
            return True
        else:
            return False
    return False

def authenticate(self, request, username=None, password=None):
    # username = phone
    try:
        user = User.objects.get(phone=username)
        if user.check_password(password):
            return user
        return None
    except (User.DoesNotExist, User.MultipleObjectsReturned):
        return None

def book_detail(request, pk, slug):
    book = get_object_or_404(Book, id=pk, slug=slug)
    reviews = book.reviews.filter(active=True).order_by('-created')

    context = {
        'book': book,
        'form': ReviewForm() if request.user.is_authenticated else None,
        'reviews': reviews,
    }
    return render(request, "store/detail.html", context)

def validate_base_url(base_url: str) -> str:
    """Return a normalized HTTP(S) base URL without embedded credentials or query data."""
    if not isinstance(base_url, str) or not base_url.strip():
        raise ValueError("OpenAI-compatible base_url is required")
    normalized = base_url.strip().rstrip("/")
    parsed = urlsplit(normalized)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError("OpenAI-compatible base_url must be an absolute HTTP(S) URL")
    if parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise ValueError("OpenAI-compatible base_url must not contain credentials, query, or fragment")
    return normalized

def _json_text(self, text: str) -> str:
    if not isinstance(text, str) or not text.strip():
        raise DocumentationError("invalid_output", "Model output is empty")
    stripped = text.strip()
    if not stripped.startswith("```"):
        return stripped
    lines = stripped.splitlines()
    if (
        stripped.count("```") != 2
        or len(lines) < 3
        or lines[0].strip().lower() not in {"```", "```json"}
        or lines[-1].strip() != "```"
    ):
        raise DocumentationError("invalid_output", "Model output contains an invalid Markdown fence")
    return "\n".join(lines[1:-1]).strip()

